func (r *ConnectorOwnerEntitlementDataSourceModel) RefreshFromSharedSearchConnectorEntitlementOwnersResponse(ctx context.Context, resp *shared.SearchConnectorEntitlementOwnersResponse) diag.Diagnostics {
	var diags diag.Diagnostics

	if resp != nil {
		if len(resp.List) == 0 {
			diags.AddError("Unexpected response from API", "Missing response body array data.")
			return diags
		}

		diags.Append(r.RefreshFromSharedConnectorOwnerEntitlement(ctx, &resp.List[0])...)

		if diags.HasError() {
			return diags
		}

		r.NextPageToken = types.StringPointerValue(resp.NextPageToken)
	}

	return diags
}

